import Fastify, { type FastifyInstance } from "fastify";

type Product = { id: string; name: string; price: number };
const products: Product[] = [];

export const app = Fastify({ logger: false });

async function catalog(app: FastifyInstance) {
    app.get<{ Params: { id: string } }>(
        "/products/:id",
        {
            schema: {
                params: {
                    type: "object",
                    additionalProperties: false,
                    required: ["id"],
                    properties: { id: { type: "string", minLength: 1 } },
                },
            },
        },
        async function getProduct(request, reply) {
            const product = products.find(function match(item) {
                return item.id === request.params.id;
            });
            if (product === undefined) {
                return reply.status(404).send({ error: "not_found" });
            }
            return product;
        },
    );

    app.post<{ Body: { name: string; price: number } }>(
        "/products",
        {
            schema: {
                body: {
                    type: "object",
                    additionalProperties: false,
                    required: ["name", "price"],
                    properties: {
                        name: { type: "string", minLength: 1 },
                        price: { type: "number", minimum: 0 },
                    },
                },
            },
        },
        async function createProduct(request, reply) {
            const product = {
                id: String(products.length + 1),
                name: request.body.name,
                price: request.body.price,
            };
            products.push(product);
            return reply.status(201).send(product);
        },
    );
}

app.register(catalog);
